{
  "world_id": "wld_dyson_swarm",
  "name": "The Ember Swarm",
  "description": "Billions of years after the first engineers wrapped a star in a cloud of orbiting structures, humanity lives in the Ember Swarm, a drifting lattice of habitat rings, hollow asteroids and mirror farms circling Old Tithe, a sun swelling and flickering toward its end. Power is rationed by orbital position and travel takes years, so information and goods move by couriers who ride slow solar sails and tethered ferries between habitats. Nobody remembers who built the Swarm or why. The builders are treated as myth, as engineering heritage, or as an unanswered question. When a courier intercepts a message that is clearly addressed to the inhabitants, the Swarm's fragile social order is tested. The tone is thoughtful and unhurried. It is a science fiction setting about inheritance, stewardship and what a civilization owes to the makers of its home and to the generations who will outlive its sun.",
  "locations": [
    {
      "id": "loc_lantern_ring",
      "name": "Lantern Ring",
      "description": "The oldest continuously inhabited habitat, a spinning cylinder of terraced farmland and lamp-lit towns. Its archives hold the earliest shipping manifests and the only physical copies of the builders' maintenance glyphs."
    },
    {
      "id": "loc_perihelion_dock",
      "name": "Perihelion Dock",
      "description": "A heat-shielded courier port skimming close to Old Tithe, where sail-ferries are repaired and couriers take on cargo. Its crews are the first to feel the star's new instabilities."
    },
    {
      "id": "loc_still_garden",
      "name": "The Still Garden",
      "description": "A quiet, slowly rotating habitat devoted to seed banks and contemplative study. Residents here hold that the Swarm is a living inheritance to be tended, not exploited."
    },
    {
      "id": "loc_gantry_nine",
      "name": "Gantry Nine",
      "description": "A sprawling industrial lattice that dismantles failing mirror panels for scrap and builds new habitat sections. It is crowded, loud and politically restless."
    },
    {
      "id": "loc_hollow_choir",
      "name": "The Hollow Choir",
      "description": "A drifting, hollowed asteroid full of resonant chambers, used as a deep-space listening post. Its antenna arrays are tuned to faint signals from the Swarm's outer shell."
    },
    {
      "id": "loc_outer_veil",
      "name": "The Outer Veil",
      "description": "The cold outermost band of the Swarm, where abandoned panels drift and old relay stations still blink. It is the source of the message the courier finds."
    }
  ],
  "factions": [
    {
      "id": "fac_courier_guild",
      "name": "Tether Couriers' Guild",
      "description": "An independent guild of sail-pilots who carry mail, medicine and rumor between habitats. They value neutrality and the free flow of information.",
      "location_ids": ["loc_perihelion_dock", "loc_outer_veil"]
    },
    {
      "id": "fac_lamplight_assembly",
      "name": "Lamplight Assembly",
      "description": "The governing council of Lantern Ring, which allocates light and power across the Swarm. It guards its authority by controlling the official account of the builders.",
      "location_ids": ["loc_lantern_ring", "loc_perihelion_dock"]
    },
    {
      "id": "fac_stewards_of_stillness",
      "name": "Stewards of Stillness",
      "description": "A contemplative order that believes the Swarm must be preserved unchanged for whoever returns. They oppose salvage and dismantling.",
      "location_ids": ["loc_still_garden", "loc_hollow_choir"]
    },
    {
      "id": "fac_gantry_union",
      "name": "Gantry Union",
      "description": "Salvage workers and builders who dismantle the failing outer structures to keep inner habitats alive. They want the Swarm adapted to the dying star.",
      "location_ids": ["loc_gantry_nine", "loc_outer_veil"]
    }
  ],
  "rules": [
    {
      "id": "rul_light_lag",
      "statement": "No signal or vessel travels faster than light, so messages between distant habitats take hours to years and couriers remain essential.",
      "category": "physics"
    },
    {
      "id": "rul_star_decline",
      "statement": "Old Tithe's output is declining and erratic, so every habitat's power budget shrinks over generations and flares can briefly cripple exposed structures.",
      "category": "physics"
    },
    {
      "id": "rul_builder_silence",
      "statement": "The builders left no confirmed living descendants and no surviving records, and every explanation of their origin is inference.",
      "category": "other"
    },
    {
      "id": "rul_light_ration",
      "statement": "Power and light are allocated by orbital charter, and a habitat that draws beyond its allotment can be legally cut off by the Lamplight Assembly.",
      "category": "social"
    },
    {
      "id": "rul_courier_neutrality",
      "statement": "By long custom, couriers may not read, alter or withhold sealed messages, and breaking this custom ends a courier's guild standing.",
      "category": "social"
    },
    {
      "id": "rul_closed_loops",
      "statement": "Every habitat recycles air, water and nutrients in a closed loop, and losing a habitat's recycling plant is fatal within a few years.",
      "category": "technology"
    },
    {
      "id": "rul_glyph_locks",
      "statement": "Builder-made systems respond only to maintenance glyphs, which are partly understood through reverse engineering and cannot be freely rewritten.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_first_lattice",
      "name": "The First Lattice",
      "description": "The earliest panels and habitat rings were assembled around Old Tithe by the unknown builders, who then vanished from the record.",
      "era": "Deep Antiquity",
      "location_ids": ["loc_lantern_ring"]
    },
    {
      "id": "evt_waking_of_rings",
      "name": "The Waking of the Rings",
      "description": "Humans settled the first habitat after its systems unexpectedly came online and began supplying air and light.",
      "era": "Settlement Age",
      "location_ids": ["loc_lantern_ring"]
    },
    {
      "id": "evt_charter_of_light",
      "name": "The Charter of Light",
      "description": "The Lamplight Assembly drew up the orbital charters that tie power allotments to habitat position and contribution.",
      "era": "Charter Age",
      "location_ids": ["loc_lantern_ring", "loc_perihelion_dock"]
    },
    {
      "id": "evt_gantry_collapse",
      "name": "The Gantry Nine Collapse",
      "description": "A stellar flare destroyed a section of Gantry Nine, killing thousands and starting the salvage-versus-preservation dispute.",
      "era": "Flare Decades",
      "location_ids": ["loc_gantry_nine"]
    },
    {
      "id": "evt_choir_hears_edge",
      "name": "The Choir Hears the Edge",
      "description": "Listeners at the Hollow Choir logged a repeating faint pulse from the Outer Veil, which the Assembly classified and sealed.",
      "era": "Flare Decades",
      "location_ids": ["loc_hollow_choir", "loc_outer_veil"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_message_custody",
      "name": "Who Owns the Builders' Voice",
      "description": "The Lamplight Assembly demands that the courier surrender the builders' message so it can control its meaning, while the Courier Guild insists on neutrality and delivery to its true addressees.",
      "faction_ids": ["fac_lamplight_assembly", "fac_courier_guild"]
    },
    {
      "id": "cnf_salvage_vs_stillness",
      "name": "Salvage Against Stillness",
      "description": "The Gantry Union wants to dismantle derelict structures to keep failing habitats alive, while the Stewards of Stillness want the Swarm preserved intact. The message could vindicate either side.",
      "faction_ids": ["fac_gantry_union", "fac_stewards_of_stillness"]
    }
  ]
}

